def sheet_to_records(sheet: dict[str, object]) -> list[dict[str, object]]:
    columns = list(sheet.get("columns", []))
    return [dict(zip(columns, row)) for row in sheet.get("rows", [])]

def rule_counts() -> dict[str, int]:
    return {
        "removed_parties": len(DEFAULT_FILTER_RULES["Removed Party"]["rows"]),
        "change_format": len(DEFAULT_FILTER_RULES["Change Format"]["rows"]),
        "tolerance": len(DEFAULT_FILTER_RULES["Tolerance"]["rows"]),
        "no_need": len(DEFAULT_NO_NEED_RULES["Removed"]["rows"]),
    }
